// Build the SeaLink daily logistics brief from Odoo data
const TZ_OFFSET_H = 8; // Philippines (UTC+8)
const pickings = $('Get open transfers').all().map(i => i.json).filter(p => p.name);
const moves    = $('Get open move lines').all().map(i => i.json).filter(m => m.picking_id);
const products = $('Get products').all().map(i => i.json).filter(p => p.default_code);

const m2o = v => Array.isArray(v) ? v[1] : (v || '');
const m2oId = v => Array.isArray(v) ? v[0] : v;
const toLocal = s => new Date(new Date(String(s).replace(' ', 'T') + 'Z').getTime() + TZ_OFFSET_H * 3600e3);
const fmt = d => d.toUTCString().slice(0, 11); // e.g. "Mon, 09 Nov"
const now = new Date(Date.now() + TZ_OFFSET_H * 3600e3);
const daysAway = s => (toLocal(s) - now) / 86400e3;

// Minimum free stock per item (others default to 3)
const MIN = { 'SP-SAF-002': 20, 'SP-NAV-001': 20, 'SP-AE-001': 10, 'SP-DK-002': 5 };

const lines = [];
lines.push(`⚓ SeaLink Daily Logistics Brief – ${fmt(now)}`);
lines.push('Manila Spares Warehouse (demo data)');

// Deliveries to vessels due within 2 days
const out = pickings.filter(p => p.picking_type_code === 'outgoing' && daysAway(p.scheduled_date) <= 2)
                    .sort((a, b) => a.scheduled_date.localeCompare(b.scheduled_date));
lines.push('');
lines.push(`🚚 Vessel deliveries due (next 48h): ${out.length}`);
let shortCount = 0;
for (const p of out) {
  lines.push(`• ${p.name} → ${m2o(p.partner_id)} | ${p.origin || '-'} | ${fmt(toLocal(p.scheduled_date))}`);
  for (const m of moves.filter(m => m2oId(m.picking_id) === p.id)) {
    if ((m.quantity || 0) < m.product_uom_qty) {
      shortCount++;
      lines.push(`   ⚠️ SHORT: ${m2o(m.product_id)} – need ${m.product_uom_qty}, reserved ${m.quantity || 0}`);
    }
  }
}
if (!out.length) lines.push('• None');

// Incoming receipts within 3 days
const inc = pickings.filter(p => p.picking_type_code === 'incoming' && daysAway(p.scheduled_date) <= 3);
lines.push('');
lines.push(`📦 Incoming from suppliers (next 3 days): ${inc.length}`);
for (const p of inc) lines.push(`• ${p.name} ← ${m2o(p.partner_id)} | ${p.origin || '-'} | ${fmt(toLocal(p.scheduled_date))}`);
if (!inc.length) lines.push('• None');

// Low stock (free quantity at or below minimum)
const low = products.filter(p => (p.free_qty ?? p.qty_available) <= (MIN[p.default_code] ?? 3));
lines.push('');
lines.push(`🔻 Low stock (free qty ≤ minimum): ${low.length}`);
for (const p of low) lines.push(`• [${p.default_code}] ${p.name} – free ${p.free_qty ?? p.qty_available}, min ${MIN[p.default_code] ?? 3}`);
if (!low.length) lines.push('• None');

lines.push('');
lines.push(shortCount || low.length ? 'Action: review shortages and raise purchase orders.' : 'All good. No action needed.');

return [{ json: { message: lines.join('\n'), deliveries: out.length, shortages: shortCount, low_stock: low.length } }];
